local _tmecmg = 36
local _vfsouo = 55
local _vwbogo = 45
local _ufauwm = ""

local _rbvnth = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _efpyek(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _wmunev(d)
	d = d:gsub("[^" .. _rbvnth .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_rbvnth:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _ptewji = _wmunev(_ufauwm)
local _aaqouq = { _tmecmg, _vfsouo, _vwbogo }
local _rnejup = {}
for i = 1, #_ptewji do
	_rnejup[i] = string.char(_efpyek(_ptewji:byte(i), _aaqouq[(i - 1) % 3 + 1]))
end

local _wflvbd = load or loadstring
local _rvqsli, _uujesy = _wflvbd(table.concat(_rnejup), "=w")
if not _rvqsli then
	gg.alert("Corrupted file: " .. tostring(_uujesy))
	os.exit()
end
